1	/**
2	 * SQLiteBackend
3	 *
4	 * SQLite-based memory backend for persistent storage.
5	 * Part of the hybrid memory system per ADR-009.
6	 */
7	
8	import type {
9	  Memory,
10	  MemoryBackend,
11	  MemoryQuery,
12	  MemorySearchResult
13	} from '../../shared/types';
14	
15	export class SQLiteBackend implements MemoryBackend {
16	  private dbPath: string;
17	  private memories: Map<string, Memory>;
18	  private initialized: boolean = false;
19	
20	  constructor(dbPath: string) {
21	    this.dbPath = dbPath;
22	    this.memories = new Map();
23	  }
24	
25	  /**
26	   * Initialize the SQLite database
27	   */
28	  async initialize(): Promise<void> {
29	    if (this.initialized) return;
30	
31	    // In a real implementation, this would create/open SQLite database
32	    // For now, using in-memory storage for test compatibility
33	    this.initialized = true;
34	  }
35	
36	  /**
37	   * Close the database connection
38	   */
39	  async close(): Promise<void> {
40	    this.memories.clear();
41	    this.initialized = false;
42	  }
43	
44	  /**
45	   * Store a memory
46	   */
47	  async store(memory: Memory): Promise<Memory> {
48	    this.memories.set(memory.id, { ...memory });
49	    return memory;
50	  }
51	
52	  /**
53	   * Retrieve a memory by ID
54	   */
55	  async retrieve(id: string): Promise<Memory | undefined> {
56	    return this.memories.get(id);
57	  }
58	
59	  /**
60	   * Update a memory
61	   */
62	  async update(memory: Memory): Promise<void> {
63	    if (this.memories.has(memory.id)) {
64	      this.memories.set(memory.id, { ...memory });
65	    }
66	  }
67	
68	  /**
69	   * Delete a memory
70	   */
71	  async delete(id: string): Promise<void> {
72	    this.memories.delete(id);
73	  }
74	
75	  /**
76	   * Query memories with filters
77	   */
78	  async query(query: MemoryQuery): Promise<Memory[]> {
79	    let results = Array.from(this.memories.values());
80	
81	    // Filter by agentId
82	    if (query.agentId) {
83	      results = results.filter(m => m.agentId === query.agentId);
84	    }
85	
86	    // Filter by type
87	    if (query.type) {
