102	  /**
103	   * Initialize the SQLite backend
104	   */
105	  async initialize(): Promise<void> {
106	    if (this.initialized) return;
107	
108	    let DatabaseCtor: DatabaseCtor;
109	    try {
110	      DatabaseCtor = (await import('better-sqlite3')).default as DatabaseCtor;
111	    } catch (err) {
112	      throw new Error(
113	        "@claude-flow/memory: SQLiteBackend requires the optional 'better-sqlite3' package. " +
114	        "Install it with `npm i better-sqlite3` or use a different DatabaseProvider " +
115	        "(sql.js / rvf / json). Original error: " + (err instanceof Error ? err.message : String(err))
116	      );
117	    }
118	
119	    // Open database connection
120	    this.db = new DatabaseCtor(this.config.databasePath, {
121	      verbose: this.config.verbose ? console.log : undefined,
122	    });
123	
124	    // Enable WAL mode for better concurrency
125	    if (this.config.walMode) {
126	      this.db.pragma('journal_mode = WAL');
127	    }
128	
129	    // Performance optimizations
130	    if (this.config.optimize) {
131	      this.db.pragma('synchronous = NORMAL');
132	      this.db.pragma('cache_size = 10000');
133	      this.db.pragma('temp_store = MEMORY');
134	    }
135	
136	    // Create schema
137	    this.createSchema();
138	
139	    this.initialized = true;
140	    this.emit('initialized');
