348	  /**
349	   * Query memory entries with filters
350	   */
351	  async query(query: MemoryQuery): Promise<MemoryEntry[]> {
352	    this.ensureInitialized();
353	    const startTime = performance.now();
354	
355	    let sql = 'SELECT * FROM memory_entries WHERE 1=1';
356	    const params: any[] = [];
357	
358	    // Build WHERE clauses
359	    if (query.namespace) {
360	      sql += ' AND namespace = ?';
361	      params.push(query.namespace);
362	    }
363	
364	    if (query.key) {
365	      sql += ' AND key = ?';
366	      params.push(query.key);
367	    }
368	
369	    if (query.keyPrefix) {
370	      sql += ' AND key LIKE ?';
371	      params.push(`${query.keyPrefix}%`);
372	    }
373	
374	    if (query.memoryType) {
375	      sql += ' AND type = ?';
376	      params.push(query.memoryType);
377	    }
378	
379	    if (query.accessLevel) {
380	      sql += ' AND access_level = ?';
381	      params.push(query.accessLevel);
382	    }
383	
384	    if (query.ownerId) {
385	      sql += ' AND owner_id = ?';
386	      params.push(query.ownerId);
387	    }
388	
389	    if (query.createdAfter) {
390	      sql += ' AND created_at >= ?';
391	      params.push(query.createdAfter);
392	    }
393	
394	    if (query.createdBefore) {
395	      sql += ' AND created_at <= ?';
396	      params.push(query.createdBefore);
397	    }
398	
399	    if (query.updatedAfter) {
400	      sql += ' AND updated_at >= ?';
401	      params.push(query.updatedAfter);
402	    }
403	
404	    if (query.updatedBefore) {
405	      sql += ' AND updated_at <= ?';
406	      params.push(query.updatedBefore);
407	    }
408	
409	    if (!query.includeExpired) {
410	      sql += ' AND (expires_at IS NULL OR expires_at > ?)';
411	      params.push(Date.now());
412	    }
413	
414	    // Tag filtering (safe parameterized query)
415	    if (query.tags && query.tags.length > 0) {
416	      // Validate tags before using in query
417	      for (const tag of query.tags) {
418	        if (typeof tag !== 'string' || !/^[a-zA-Z0-9_\-.:]+$/.test(tag)) {
419	          throw new Error(`Invalid tag format: ${tag}`);
420	        }
421	      }
422	      // Use parameterized query with JSON functions
423	      const tagPlaceholders = query.tags.map(() => '?').join(', ');
424	      sql += ` AND EXISTS (
425	        SELECT 1 FROM json_each(tags) AS t
426	        WHERE t.value IN (${tagPlaceholders})
427	      )`;
428	      params.push(...query.tags);
429	    }
430	
431	    // Pagination
432	    sql += ' ORDER BY created_at DESC';
433	    if (query.limit) {
434	      sql += ' LIMIT ?';
435	      params.push(query.limit);
436	    }
437	    if (query.offset) {
438	      sql += ' OFFSET ?';
439	      params.push(query.offset);
440	    }
441	
442	    const stmt = this.db!.prepare(sql);
443	    const rows = stmt.all(...params) as any[];
444	
445	    const results = rows.map((row) => this.rowToEntry(row));
446	
447	    const duration = performance.now() - startTime;
448	    this.stats.queryCount++;
449	    this.stats.totalQueryTime += duration;
450	
451	    return results;
452	  }
