83	      // Initialize sql.js (loads WASM)
84	      this.SQL = await initSqlJs();
85	
86	      // Ensure directory exists
87	      const dir = dirname(this.dbPath);
88	      if (!existsSync(dir)) {
89	        mkdirSync(dir, { recursive: true });
90	      }
91	
92	      // Load existing database or create new
93	      if (existsSync(this.dbPath)) {
94	        const fileBuffer = readFileSync(this.dbPath);
95	        this.db = new this.SQL.Database(fileBuffer);
96	      } else {
97	        this.db = new this.SQL.Database();
98	      }
99	
100	      // Create schema
101	      this.db.run(`
102	        CREATE TABLE IF NOT EXISTS embeddings (
103	          key TEXT PRIMARY KEY,
104	          embedding BLOB NOT NULL,
105	          dimensions INTEGER NOT NULL,
106	          created_at INTEGER NOT NULL,
107	          accessed_at INTEGER NOT NULL,
108	          access_count INTEGER DEFAULT 1
109	        )
110	      `);
111	      this.db.run('CREATE INDEX IF NOT EXISTS idx_accessed_at ON embeddings(accessed_at)');
112	      this.db.run('CREATE INDEX IF NOT EXISTS idx_created_at ON embeddings(created_at)');
113	
114	      // Clean expired entries on startup
115	      this.cleanExpired();
116	
117	      // Save after initialization to persist schema
118	      this.saveToFile();
119	
120	      // Start auto-save timer
121	      this.startAutoSave();
122	
123	      this.initialized = true;
124	    } catch (error) {
125	      // If sql.js not available, fall back gracefully
126	      console.warn('[persistent-cache] sql.js not available, cache disabled:',
127	        error instanceof Error ? error.message : error);
