171	  /**
172	   * Generate cache key from text
173	   */
174	  private hashKey(text: string): string {
175	    // FNV-1a hash for fast, deterministic key generation
176	    let hash = 0x811c9dc5;
177	    for (let i = 0; i < text.length; i++) {
178	      hash ^= text.charCodeAt(i);
179	      hash = (hash * 0x01000193) >>> 0;
180	    }
181	    return `emb_${hash.toString(16)}_${text.length}`;
182	  }
