390	  /**
391	   * ADR-125 Phase 5 — keyword (FTS5) search.
392	   *
393	   * Mirrors the SQLiteBackend.searchKeyword shape. Falls back to a LIKE
394	   * scan when FTS5 isn't available on the sql.js build.
395	   */
396	  async searchKeyword(query: string, limit: number = 10): Promise<SearchResult[]> {
397	    this.ensureInitialized();
398	    if (!query || !query.trim()) return [];
399	
400	    if (this.ftsAvailable) {
401	      try {
402	        const stmt = this.db!.prepare(`
403	          SELECT e.*, fts.rank as fts_rank
404	          FROM memory_fts AS fts
405	          JOIN memory_entries AS e ON e.id = fts.id
406	          WHERE memory_fts MATCH ?
407	          ORDER BY fts.rank
408	          LIMIT ?
409	        `);
410	        stmt.bind([escapeFtsQuery(query), limit]);
411	        const results: SearchResult[] = [];
412	        while (stmt.step()) {
413	          const row: any = stmt.getAsObject();
414	          const entry = this.rowToEntry(row);
415	          const score = 1 / (1 + Math.abs(row.fts_rank || 0));
416	          results.push({ entry, score, distance: 1 - score });
417	        }
418	        stmt.free();
419	        return results;
420	      } catch {
421	        // Fall through to LIKE
422	      }
423	    }
424	
425	    // LIKE fallback
426	    const like = `%${query.replace(/[%_]/g, '')}%`;
427	    const stmt = this.db!.prepare(
428	      'SELECT * FROM memory_entries WHERE content LIKE ? ORDER BY updated_at DESC LIMIT ?'
429	    );
430	    stmt.bind([like, limit]);
431	    const results: SearchResult[] = [];
432	    while (stmt.step()) {
433	      const row: any = stmt.getAsObject();
434	      results.push({
435	        entry: this.rowToEntry(row),
436	        score: 0.5,
437	        distance: 0.5,
438	      });
439	    }
440	    stmt.free();
441	    return results;
442	  }
