144	async function migrateBatches(
145	  items: Record<string, unknown>[],
146	  rvfPath: string,
147	  options: RvfMigrationOptions,
148	  normalize?: (r: Record<string, unknown>) => Record<string, unknown>,
149	): Promise<{ migrated: number; errors: string[] }> {
150	  const batchSize = options.batchSize ?? 500;
151	  const dimensions = options.dimensions ?? 1536;
152	  const backend = new RvfBackend({ databasePath: rvfPath, dimensions, verbose: options.verbose });
153	  await backend.initialize();
154	  let migrated = 0;
155	  const errors: string[] = [];
156	  try {
157	    for (let i = 0; i < items.length; i += batchSize) {
158	      const batch = items.slice(i, i + batchSize);
159	      const entries: MemoryEntry[] = [];
160	      for (const item of batch) {
161	        try {
162	          entries.push(fillDefaults(normalize ? normalize(item) : item));
163	        } catch (e) { errors.push(`Entry ${item.id ?? i}: ${(e as Error).message}`); }
164	      }
165	      if (entries.length > 0) { await backend.bulkInsert(entries); migrated += entries.length; }
166	      options.onProgress?.({ current: Math.min(i + batchSize, items.length), total: items.length, phase: 'migrating' });
167	    }
168	  } finally { await backend.shutdown(); }
169	  return { migrated, errors };

