559	  /**
560	   * Semantic vector search (limited without vector index)
561	   */
562	  async search(embedding: Float32Array, options: SearchOptions): Promise<SearchResult[]> {
563	    this.ensureInitialized();
564	
565	    // Get all entries with embeddings
566	    const entries = await this.query({
567	      type: 'hybrid',
568	      limit: options.filters?.limit || 1000,
569	    });
570	
571	    // Calculate cosine similarity for each entry
572	    const results: SearchResult[] = [];
573	
574	    for (const entry of entries) {
575	      if (!entry.embedding) continue;
576	
577	      const similarity = this.cosineSimilarity(embedding, entry.embedding);
578	
579	      if (options.threshold && similarity < options.threshold) {
580	        continue;
581	      }
582	
583	      results.push({
584	        entry,
585	        score: similarity,
586	        distance: 1 - similarity,
587	      });
588	    }
589	
590	    // Sort by score descending
591	    results.sort((a, b) => b.score - a.score);
592	
593	    // Return top k results
594	    return results.slice(0, options.k);
595	  }
