824	  private cosineSimilarity(a: Float32Array, b: Float32Array): number {
825	    let dotProduct = 0;
826	    let normA = 0;
827	    let normB = 0;
828	
829	    for (let i = 0; i < a.length; i++) {
830	      dotProduct += a[i] * b[i];
831	      normA += a[i] * a[i];
832	      normB += b[i] * b[i];
833	    }
834	
835	    if (normA === 0 || normB === 0) return 0;
836	
837	    return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
838	  }
