849	/**
850	 * Escape an FTS5 MATCH query string. Wraps each whitespace-separated
851	 * token as a quoted phrase so prose input doesn't trip FTS5's mini-language.
852	 * @internal
853	 */
854	function escapeFtsQuery(q: string): string {
855	  return q
856	    .split(/\s+/)
857	    .filter(Boolean)
858	    .map((tok) => `"${tok.replace(/"/g, '""')}"`)
859	    .join(' ');
860	}
